<?php
declare(strict_types=1); function mg_personal_workflows_resolve_gift(PDO $pdo, int $userId, string $giftPublicId): array { if(!mg_personal_agent_table_exists($pdo,'gifts')) throw new RuntimeException('Gift lifecycle schema is unavailable.'); $stmt=$pdo->prepare("SELECT g.*,gc.status claim_status,gc.expires_at claim_expires_at
        FROM gifts g LEFT JOIN gift_claims gc ON gc.gift_id=g.id
        WHERE g.public_id=? AND (g.sender_user_id=? OR g.recipient_user_id=?) LIMIT 1"); $stmt->execute([$giftPublicId,$userId,$userId]); $gift=$stmt->fetch(PDO::FETCH_ASSOC); if(!$gift) throw new RuntimeException('Gift not found.'); return $gift; } function mg_personal_workflows_create_lifecycle_reminder(PDO $pdo, int $userId, array $input): array { mg_personal_workflows_require_schema($pdo); $giftPublicId=mg_personal_agent_text($input['gift_id'] ?? '',80); if($giftPublicId==='') throw new InvalidArgumentException('Choose a gift.'); $gift=mg_personal_workflows_resolve_gift($pdo,$userId,$giftPublicId); $kind=mg_personal_agent_text($input['reminder_kind'] ?? 'claim',30); if(!in_array($kind,['claim','redemption','expiry'],true)) throw new InvalidArgumentException('Choose a valid reminder type.'); $isSender=(int)$gift['sender_user_id']===$userId; $targetUserId=0; if($isSender) { $targetUserId=(int)($gift['recipient_user_id'] ?? 0); if($targetUserId<1) throw new RuntimeException('This gift does not have a Microgifter recipient available for an in-app reminder.'); } else { $targetUserId=$userId; if($kind==='claim' && (string)$gift['status']==='claimed') throw new RuntimeException('This gift is already claimed.'); } $validStates=['sent','delivered','claimed']; if(!in_array((string)$gift['status'],$validStates,true)) throw new RuntimeException('This gift is not eligible for a lifecycle reminder.'); if($kind==='redemption' && !in_array((string)($gift['claim_status'] ?? ''),['verified','redeemed'],true)) { throw new RuntimeException('Redemption reminders require a verified claim.'); } $remindAt=mg_personal_agent_datetime($input['remind_at'] ?? ''); $message=mg_personal_agent_nullable_text($input['message'] ?? null,500); if($message!==null && mg_personal_workflows_sensitive_text($message)) throw new InvalidArgumentException('Reminder messages cannot contain credentials or payment details.'); $status=mg_personal_workflows_bool($input['schedule_now'] ?? true,true)?'scheduled':'draft'; $publicId=mg_public_uuid(); try { $pdo->prepare("INSERT INTO user_gift_lifecycle_reminders
            (public_id,owner_user_id,gift_id,target_user_id,reminder_kind,remind_at,status,delivery_channel,message,created_at,updated_at)
            VALUES (?,?,?,?,?,?,?,'in_app',?,NOW(),NOW())") ->execute([$publicId,$userId,(int)$gift['id'],$targetUserId,$kind,$remindAt,$status,$message]); } catch(PDOException $e) { if((string)$e->getCode()==='23000') throw new RuntimeException('A reminder already exists for that gift, type, and time.'); throw $e; } mg_audit('user_gift_lifecycle_reminder.created','user_gift_lifecycle_reminder',['reminder_id'=>$publicId,'gift_id'=>$giftPublicId,'kind'=>$kind,'delivery_channel'=>'in_app'],$userId); foreach(mg_personal_workflows_lifecycle_reminders($pdo,$userId) as $row) if($row['id']===$publicId) return $row; throw new RuntimeException('Unable to load the lifecycle reminder.'); } function mg_personal_workflows_update_lifecycle_reminder(PDO $pdo, int $userId, string $publicId, string $action): array { $action=mg_personal_agent_text($action,30); $stmt=$pdo->prepare("SELECT r.*,g.public_id gift_public_id,g.title gift_title,g.status gift_status
        FROM user_gift_lifecycle_reminders r INNER JOIN gifts g ON g.id=r.gift_id
        WHERE r.owner_user_id=? AND r.public_id=? LIMIT 1"); $stmt->execute([$userId,$publicId]); $row=$stmt->fetch(PDO::FETCH_ASSOC); if(!$row) throw new RuntimeException('Lifecycle reminder not found.'); $current=(string)$row['status']; if($action==='schedule') { if($current!=='draft') throw new RuntimeException('Only draft reminders can be scheduled.'); $next='scheduled'; } elseif($action==='send_now') { if(!in_array($current,['draft','scheduled'],true)) throw new RuntimeException('This reminder cannot be sent.'); $title=match((string)$row['reminder_kind']) { 'redemption'=>'Microgift redemption reminder', 'expiry'=>'Microgift expiry reminder', default=>'Microgift claim reminder', }; $body=(string)($row['message'] ?: ('Review “'.(string)$row['gift_title'].'” in your Microgifter account.')); $notificationId=mg_personal_workflows_notify($pdo,(int)$row['target_user_id'],'gift_lifecycle_reminder',$title,$body,'/inbox.php',(int)$row['gift_id']); if($notificationId===null) throw new RuntimeException('In-app notifications are unavailable.'); $pdo->prepare("UPDATE user_gift_lifecycle_reminders SET notification_id=?,status='sent',sent_at=NOW(),updated_at=NOW() WHERE id=? AND owner_user_id=?") ->execute([$notificationId,(int)$row['id'],$userId]); mg_audit('user_gift_lifecycle_reminder.sent','user_gift_lifecycle_reminder',['reminder_id'=>$publicId,'gift_id'=>$row['gift_public_id'],'notification_id'=>$notificationId,'gift_state_changed'=>false],$userId); foreach(mg_personal_workflows_lifecycle_reminders($pdo,$userId) as $item) if($item['id']===$publicId) return $item; throw new RuntimeException('Lifecycle reminder not found.'); } elseif($action==='dismiss') { if(!in_array($current,['draft','scheduled'],true)) throw new RuntimeException('This reminder cannot be dismissed.'); $next='dismissed'; } elseif($action==='cancel') { if(!in_array($current,['draft','scheduled'],true)) throw new RuntimeException('This reminder cannot be cancelled.'); $next='cancelled'; } else { throw new InvalidArgumentException('Invalid lifecycle reminder action.'); } $pdo->prepare("UPDATE user_gift_lifecycle_reminders SET status=?,dismissed_at=IF(?='dismissed',NOW(),dismissed_at),cancelled_at=IF(?='cancelled',NOW(),cancelled_at),updated_at=NOW() WHERE id=? AND owner_user_id=?") ->execute([$next,$next,$next,(int)$row['id'],$userId]); mg_audit('user_gift_lifecycle_reminder.status_updated','user_gift_lifecycle_reminder',['reminder_id'=>$publicId,'from'=>$current,'to'=>$next,'gift_state_changed'=>false],$userId); foreach(mg_personal_workflows_lifecycle_reminders($pdo,$userId) as $item) if($item['id']===$publicId) return $item; throw new RuntimeException('Lifecycle reminder not found.'); } 